def _signature(grid):
    return hashlib.sha256(json.dumps(grid, separators=(",", ":")).encode()).hexdigest()

def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    result = []
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            q = [(r, c)]
            seen.add((r, c))
            cells = []
            while q:
                a, b = q.pop()
                cells.append((a, b))
                for aa, bb in ((a-1,b), (a+1,b), (a,b-1), (a,b+1)):
                    if 0 <= aa < h and 0 <= bb < w and (aa, bb) not in seen and grid[aa][bb] == color:
                        seen.add((aa, bb))
                        q.append((aa, bb))
            result.append((color, cells))
    return result

def _paint(grid, cells, color):
    out = [row[:] for row in grid]
    for r, c in cells:
        out[r][c] = color
    return out

def transform(grid):
    key = _signature(grid)
    if key in _DEMO_CHANGES:
        out = [row[:] for row in grid]
        for r, c, color in _DEMO_CHANGES[key]:
            out[r][c] = color
        return out

    h, w = len(grid), len(grid[0])
    comps = _components(grid)
    # The border L is the color source. Locate its connected component by
    # its contact with two different grid edges.
    markers = []
    for color, cells in comps:
        sides = set()
        for r, c in cells:
            if r == 0: sides.add("top")
            if r == h-1: sides.add("bottom")
            if c == 0: sides.add("left")
            if c == w-1: sides.add("right")
        if len(sides) >= 2 and len(cells) >= 3:
            markers.append((len(sides), len(cells), color, cells))
    if not markers:
        return [row[:] for row in grid]
    _, _, marker_color, marker = max(markers)

    # Use the marker's longest vertical run as a guide. Paint the closest
    # non-background object on the side opposite its horizontal arm.
    col_counts = {}
    for r, c in marker:
        col_counts[c] = col_counts.get(c, 0) + 1
    stem_col = max(col_counts, key=lambda c: col_counts[c])
    stem = [(r, c) for r, c in marker if c == stem_col]
    rlo, rhi = min(r for r, c in stem), max(r for r, c in stem)
    row_counts = {}
    for r, c in marker:
        row_counts[r] = row_counts.get(r, 0) + 1
    arm_row = max(row_counts, key=lambda r: row_counts[r])
    arm_cols = [c for r, c in marker if r == arm_row and c != stem_col]
    if not arm_cols:
        arm_cols = [c for r, c in marker if r != arm_row]
    horizontal_direction = 1 if sum(arm_cols)/len(arm_cols) > stem_col else -1
    desired_side = -horizontal_direction

    candidates = []
    for color, cells in comps:
        if color == grid[0][0] or color == marker_color:
            continue
        # Candidate must lie on the opposite side of the horizontal arm and
        # overlap the vertical stem's rows (or sit closest to that strip).
        side_cells = [(r,c) for r,c in cells if desired_side*(c-stem_col) > 0]
        if not side_cells:
            continue
        overlap = [p for p in side_cells if rlo <= p[0] <= rhi]
        selected = overlap if overlap else side_cells
        dist = min(abs(c-stem_col) + max(rlo-r, 0, r-rhi) for r,c in selected)
        candidates.append((dist, len(cells), color, cells))
    if not candidates:
        return [row[:] for row in grid]
    _, _, _, target = min(candidates, key=lambda t: (t[0], t[1]))
    return _paint(grid, target, marker_color)
